use std::collections::HashMap;
use std::path::{Path, PathBuf};
use std::env;
use std::fs;
use std::io::{self, Write};
use std::process::Command;

// ─── Error types ──────────────────────────────────────────────────────────────

#[derive(Debug)]
enum HandlrError {
    Io(io::Error),
    NotFound(String),
    MimeParse(String),
    Other(String),
}

impl std::fmt::Display for HandlrError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            HandlrError::Io(e) => write!(f, "Io({:?})", e),
            HandlrError::NotFound(s) => write!(f, "Not found: {}", s),
            HandlrError::MimeParse(s) => write!(f, "mime parse error: {}", s),
            HandlrError::Other(s) => write!(f, "{}", s),
        }
    }
}

impl From<io::Error> for HandlrError {
    fn from(e: io::Error) -> Self {
        HandlrError::Io(e)
    }
}

type Result<T> = std::result::Result<T, HandlrError>;

// ─── XDG paths ────────────────────────────────────────────────────────────────

fn xdg_config_home() -> PathBuf {
    if let Ok(v) = env::var("XDG_CONFIG_HOME") {
        PathBuf::from(v)
    } else {
        let home = env::var("HOME").unwrap_or_else(|_| "/root".to_string());
        PathBuf::from(home).join(".config")
    }
}

fn xdg_data_home() -> PathBuf {
    if let Ok(v) = env::var("XDG_DATA_HOME") {
        PathBuf::from(v)
    } else {
        let home = env::var("HOME").unwrap_or_else(|_| "/root".to_string());
        PathBuf::from(home).join(".local/share")
    }
}

fn xdg_data_dirs() -> Vec<PathBuf> {
    let mut dirs = vec![xdg_data_home()];
    if let Ok(v) = env::var("XDG_DATA_DIRS") {
        dirs.extend(v.split(':').map(PathBuf::from));
    } else {
        dirs.push(PathBuf::from("/usr/local/share"));
        dirs.push(PathBuf::from("/usr/share"));
    }
    dirs
}

fn mimeapps_list_path() -> PathBuf {
    xdg_config_home().join("mimeapps.list")
}

// ─── MIME type parsing/validation ─────────────────────────────────────────────

#[derive(Debug, Clone)]
struct MimeType {
    type_: String,
    subtype: String,
}

impl MimeType {
    fn new(type_: &str, subtype: &str) -> Self {
        MimeType {
            type_: type_.to_string(),
            subtype: subtype.to_string(),
        }
    }

    fn as_str(&self) -> String {
        format!("{}/{}", self.type_, self.subtype)
    }

    fn is_wildcard(&self) -> bool {
        self.subtype == "*"
    }
}

impl std::fmt::Display for MimeType {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(f, "{}/{}", self.type_, self.subtype)
    }
}

fn parse_mime_type(s: &str) -> std::result::Result<MimeType, String> {
    if s.is_empty() {
        return Err("an invalid token was encountered, empty string".to_string());
    }

    // First char must be a letter (not '/')
    let first_char = s.chars().next().unwrap();
    if first_char == '/' {
        return Err(format!("an invalid token was encountered, 2F at position 0"));
    }

    if let Some(slash_pos) = s.find('/') {
        let type_ = &s[..slash_pos];
        let subtype = &s[slash_pos + 1..];

        if type_.is_empty() {
            return Err("a slash (/) was missing between the type and subtype".to_string());
        }

        if subtype.is_empty() {
            return Err(format!("bad mime: {}", s));
        }

        // Validate characters - no spaces or special chars except * in subtype
        Ok(MimeType::new(type_, subtype))
    } else {
        // No slash found
        // Check if it starts with a dot (extension)
        if s.starts_with('.') {
            // Extension - needs mime DB lookup
            Err(format!("could not figure out the mime type of '{}'", s))
        } else {
            Err("a slash (/) was missing between the type and subtype".to_string())
        }
    }
}

// Resolve a mime arg (could be extension like ".png" or mime type like "image/png")
fn resolve_mime(arg: &str) -> std::result::Result<MimeType, String> {
    if arg.starts_with('.') {
        // Extension - look up in mime database
        match lookup_mime_from_extension(arg) {
            Some(m) => Ok(m),
            None => Err(format!("could not figure out the mime type of '{}'", arg)),
        }
    } else {
        parse_mime_type(arg)
    }
}

// ─── MIME database (globs2 file) ──────────────────────────────────────────────

fn load_mime_globs() -> HashMap<String, String> {
    // Returns extension -> mime type mapping
    let mut globs = HashMap::new();

    for data_dir in xdg_data_dirs() {
        let globs2_path = data_dir.join("mime/globs2");
        if let Ok(content) = fs::read_to_string(&globs2_path) {
            for line in content.lines() {
                if line.starts_with('#') || line.is_empty() {
                    continue;
                }
                let parts: Vec<&str> = line.splitn(3, ':').collect();
                if parts.len() == 3 {
                    let mime = parts[1];
                    let pattern = parts[2];
                    if pattern.starts_with("*.") {
                        let ext = pattern[1..].to_lowercase(); // includes the dot
                        // Higher weight takes priority, but for simplicity just use first found
                        globs.entry(ext).or_insert_with(|| mime.to_string());
                    }
                }
            }
            // Also try globs file (older format)
        }

        // Also check globs file (format: mime:pattern)
        let globs_path = data_dir.join("mime/globs");
        if let Ok(content) = fs::read_to_string(&globs_path) {
            for line in content.lines() {
                if line.starts_with('#') || line.is_empty() {
                    continue;
                }
                let parts: Vec<&str> = line.splitn(2, ':').collect();
                if parts.len() == 2 {
                    let mime = parts[0];
                    let pattern = parts[1];
                    if pattern.starts_with("*.") {
                        let ext = pattern[1..].to_lowercase();
                        globs.entry(ext).or_insert_with(|| mime.to_string());
                    }
                }
            }
        }
    }

    globs
}

fn lookup_mime_from_extension(ext: &str) -> Option<MimeType> {
    let ext_lower = ext.to_lowercase();
    let globs = load_mime_globs();

    if let Some(mime_str) = globs.get(&ext_lower) {
        if let Ok(m) = parse_mime_type(mime_str) {
            return Some(m);
        }
    }
    None
}

fn detect_mime_from_path(path: &str) -> Option<MimeType> {
    // Check if it's a URL first
    if let Some(scheme) = get_url_scheme(path) {
        return Some(MimeType::new("x-scheme-handler", &scheme));
    }

    // Otherwise, try to detect from extension
    let p = Path::new(path);
    if let Some(ext) = p.extension() {
        let ext_str = format!(".{}", ext.to_string_lossy().to_lowercase());
        return lookup_mime_from_extension(&ext_str);
    }
    None
}

fn get_url_scheme(s: &str) -> Option<String> {
    // Check for URL scheme like "http://", "https://", "ftp://"
    if let Some(colon_pos) = s.find("://") {
        if colon_pos > 0 {
            let scheme = &s[..colon_pos];
            // Validate: scheme should be lowercase letters, digits, +, -, .
            if scheme.chars().all(|c| c.is_ascii_alphanumeric() || c == '+' || c == '-' || c == '.') {
                return Some(scheme.to_lowercase());
            }
        }
    }
    None
}

// ─── mimeapps.list reading/writing ────────────────────────────────────────────

#[derive(Debug, Default)]
struct MimeApps {
    added_associations: Vec<(String, Vec<String>)>,
    default_applications: Vec<(String, Vec<String>)>,
}

impl MimeApps {
    fn read() -> Result<Self> {
        let path = mimeapps_list_path();
        if !path.exists() {
            return Ok(MimeApps::default());
        }
        let content = fs::read_to_string(&path)?;
        Self::parse(&content)
    }

    fn parse(content: &str) -> Result<Self> {
        let mut mimeapps = MimeApps::default();
        let mut section = "";

        for line in content.lines() {
            let line = line.trim();
            if line.is_empty() || line.starts_with('#') {
                continue;
            }
            if line == "[Added Associations]" {
                section = "added";
                continue;
            }
            if line == "[Default Applications]" {
                section = "default";
                continue;
            }
            if line.starts_with('[') {
                section = "other";
                continue;
            }

            if let Some(eq_pos) = line.find('=') {
                let mime = line[..eq_pos].trim().to_string();
                let handlers_str = line[eq_pos + 1..].trim();
                let handlers: Vec<String> = handlers_str
                    .split(';')
                    .filter(|s| !s.is_empty())
                    .map(|s| s.trim().to_string())
                    .collect();

                match section {
                    "added" => mimeapps.added_associations.push((mime, handlers)),
                    "default" => mimeapps.default_applications.push((mime, handlers)),
                    _ => {}
                }
            }
        }

        Ok(mimeapps)
    }

    fn write(&self) -> Result<()> {
        let path = mimeapps_list_path();
        if let Some(parent) = path.parent() {
            fs::create_dir_all(parent)?;
        }
        let mut content = String::new();
        content.push_str("[Added Associations]\n");
        for (mime, handlers) in &self.added_associations {
            content.push_str(mime);
            content.push('=');
            content.push_str(&handlers.join(";"));
            content.push_str(";\n");
        }
        content.push('\n');
        content.push_str("[Default Applications]\n");
        for (mime, handlers) in &self.default_applications {
            content.push_str(mime);
            content.push('=');
            content.push_str(&handlers.join(";"));
            content.push_str(";\n");
        }
        fs::write(&path, content)?;
        Ok(())
    }

    fn get_default(&self, mime: &str) -> Option<&Vec<String>> {
        // First try exact match
        for (m, handlers) in &self.default_applications {
            if m == mime {
                return Some(handlers);
            }
        }
        // Then try wildcard match (e.g., "text/*")
        if let Some(slash_pos) = mime.find('/') {
            let type_ = &mime[..slash_pos];
            let wildcard = format!("{}/*", type_);
            for (m, handlers) in &self.default_applications {
                if m == &wildcard {
                    return Some(handlers);
                }
            }
        }
        None
    }

    fn set_default(&mut self, mime: &str, handler: &str) {
        for entry in &mut self.default_applications {
            if entry.0 == mime {
                entry.1 = vec![handler.to_string()];
                return;
            }
        }
        self.default_applications.push((mime.to_string(), vec![handler.to_string()]));
        // Keep sorted
        self.default_applications.sort_by(|a, b| a.0.cmp(&b.0));
    }

    fn add_handler(&mut self, mime: &str, handler: &str) {
        for entry in &mut self.default_applications {
            if entry.0 == mime {
                entry.1.push(handler.to_string());
                return;
            }
        }
        self.default_applications.push((mime.to_string(), vec![handler.to_string()]));
        self.default_applications.sort_by(|a, b| a.0.cmp(&b.0));
    }

    fn unset(&mut self, mime: &str) {
        self.default_applications.retain(|e| e.0 != mime);
    }
}

// ─── Desktop file parsing ──────────────────────────────────────────────────────

#[derive(Debug, Clone)]
struct DesktopEntry {
    name: String,
    exec: String,
    terminal: bool,
    mime_types: Vec<String>,
    no_display: bool,
    file_name: String,
}

fn parse_desktop_file(path: &Path) -> Option<DesktopEntry> {
    let content = fs::read_to_string(path).ok()?;
    let mut name = None;
    let mut exec = None;
    let mut terminal = false;
    let mut mime_types = Vec::new();
    let mut no_display = false;
    let mut in_desktop_entry = false;

    for line in content.lines() {
        let line = line.trim();
        if line == "[Desktop Entry]" {
            in_desktop_entry = true;
            continue;
        }
        if line.starts_with('[') {
            in_desktop_entry = false;
            continue;
        }
        if !in_desktop_entry {
            continue;
        }
        if line.is_empty() || line.starts_with('#') {
            continue;
        }

        if let Some(eq_pos) = line.find('=') {
            let key = line[..eq_pos].trim();
            let value = line[eq_pos + 1..].trim();
            match key {
                "Name" => { name = Some(value.to_string()); }
                "Exec" => { exec = Some(value.to_string()); }
                "Terminal" => { terminal = value.eq_ignore_ascii_case("true"); }
                "MimeType" => {
                    mime_types = value.split(';')
                        .filter(|s| !s.is_empty())
                        .map(|s| s.to_string())
                        .collect();
                }
                "NoDisplay" => { no_display = value.eq_ignore_ascii_case("true"); }
                _ => {}
            }
        }
    }

    let file_name = path.file_name()?.to_string_lossy().to_string();

    Some(DesktopEntry {
        name: name?,
        exec: exec?,
        terminal,
        mime_types,
        no_display,
        file_name,
    })
}

fn find_desktop_file(name: &str) -> Option<DesktopEntry> {
    for data_dir in xdg_data_dirs() {
        let path = data_dir.join("applications").join(name);
        if path.exists() {
            return parse_desktop_file(&path);
        }
    }
    None
}

fn validate_handler(name: &str) -> bool {
    find_desktop_file(name).is_some()
}

fn all_desktop_files() -> Vec<DesktopEntry> {
    let mut entries = Vec::new();
    let mut seen = std::collections::HashSet::new();

    for data_dir in xdg_data_dirs() {
        let apps_dir = data_dir.join("applications");
        if let Ok(read_dir) = fs::read_dir(&apps_dir) {
            let mut files: Vec<_> = read_dir
                .filter_map(|e| e.ok())
                .filter(|e| {
                    e.path().extension()
                        .map(|x| x == "desktop")
                        .unwrap_or(false)
                })
                .collect();
            files.sort_by_key(|e| e.file_name());

            for entry in files {
                let path = entry.path();
                let file_name = path.file_name().unwrap().to_string_lossy().to_string();
                if seen.contains(&file_name) {
                    continue;
                }
                if let Some(de) = parse_desktop_file(&path) {
                    seen.insert(file_name);
                    entries.push(de);
                }
            }
        }
    }
    entries
}

// ─── Exec parsing ─────────────────────────────────────────────────────────────

// Parse exec string according to desktop entry spec
// Returns (command_parts, has_field_code)
fn parse_exec(exec: &str) -> (Vec<String>, bool) {
    let mut args = Vec::new();
    let mut current = String::new();
    let mut in_quotes = false;
    let mut has_field_code = false;

    let chars: Vec<char> = exec.chars().collect();
    let mut i = 0;

    while i < chars.len() {
        let c = chars[i];

        if c == '"' {
            in_quotes = !in_quotes;
        } else if c == ' ' && !in_quotes {
            if !current.is_empty() {
                args.push(current.clone());
                current.clear();
            }
        } else if c == '%' && i + 1 < chars.len() {
            let next = chars[i + 1];
            match next {
                'f' | 'F' | 'u' | 'U' => {
                    has_field_code = true;
                    i += 1; // skip the field code char
                }
                '%' => {
                    current.push('%');
                    i += 1;
                }
                _ => {
                    current.push(c);
                }
            }
        } else {
            current.push(c);
        }

        i += 1;
    }

    if !current.is_empty() {
        args.push(current);
    }

    // Filter out empty args
    args.retain(|a| !a.is_empty());

    (args, has_field_code)
}

// Build the command string for JSON output (without the file argument)
fn exec_to_cmd_str(exec: &str) -> String {
    // Parse the exec string
    let mut result = String::new();
    let mut in_quotes = false;
    let mut after_field_code = false;
    let mut current = String::new();
    let mut parts: Vec<String> = Vec::new();
    let mut has_field_code = false;

    let chars: Vec<char> = exec.chars().collect();
    let mut i = 0;

    while i < chars.len() {
        let c = chars[i];

        if c == '"' {
            in_quotes = !in_quotes;
        } else if c == ' ' && !in_quotes {
            if !current.is_empty() {
                parts.push(current.clone());
                current.clear();
            }
        } else if c == '%' && i + 1 < chars.len() {
            let next = chars[i + 1];
            match next {
                'f' | 'F' | 'u' | 'U' => {
                    has_field_code = true;
                    // Don't add to current - skip this token
                    i += 1; // skip field code char
                }
                '%' => {
                    current.push('%');
                    i += 1;
                }
                _ => {
                    current.push(c);
                }
            }
        } else {
            current.push(c);
        }

        i += 1;
    }

    if !current.is_empty() {
        parts.push(current);
    }

    // Filter empty parts
    parts.retain(|p| !p.is_empty());

    let cmd = parts.join(" ");
    if has_field_code {
        cmd + " "
    } else {
        cmd
    }
}

// ─── Table rendering ──────────────────────────────────────────────────────────

fn render_table(rows: &[(String, String)]) {
    if rows.is_empty() {
        println!("┌──┐");
        println!("│  │");
        println!("└──┘");
        return;
    }

    let max_col1 = rows.iter().map(|(k, _)| k.chars().count()).max().unwrap_or(0);
    let max_col2 = rows.iter().map(|(_, v)| v.chars().count()).max().unwrap_or(0);

    // Total width = 2 (borders) + col1_width + 3 (│ separator + spaces) + col2_width + 2 (spaces + border)
    // = col1_width + col2_width + 7
    // But cap at 80 chars total

    let col1_inner = max_col1 + 2; // content + 2 spaces padding
    let col2_inner = max_col2 + 2; // content + 2 spaces padding

    let total_width = 2 + col1_inner + 1 + col2_inner;

    let (col1_display, col2_display) = if total_width <= 80 {
        (col1_inner, col2_inner)
    } else {
        // Need to truncate col2
        let available = 80 - 2 - col1_inner - 1;
        (col1_inner, available)
    };

    let col2_content_max = col2_display - 2; // content width

    // Print top border
    let col1_dashes = "─".repeat(col1_display);
    let col2_dashes = "─".repeat(col2_display);
    println!("┌{}┬{}┐", col1_dashes, col2_dashes);

    // Print rows
    for (key, value) in rows {
        let key_display = format!(" {} ", key);
        let key_padded = format!("{:<width$}", key_display, width = col1_display);

        let val_chars: Vec<char> = value.chars().collect();
        let val_str = if val_chars.len() > col2_content_max {
            // Truncate with +
            let truncated: String = val_chars[..col2_content_max - 1].iter().collect();
            format!("{}+", truncated)
        } else {
            value.clone()
        };
        let val_display = format!(" {} ", val_str);
        let val_padded = format!("{:<width$}", val_display, width = col2_display);

        println!("│{}│{}│", key_padded, val_padded);
    }

    // Print bottom border
    println!("└{}┴{}┘", col1_dashes, col2_dashes);
}

// ─── Command handlers ─────────────────────────────────────────────────────────

fn cmd_list(all: bool) -> Result<()> {
    let mimeapps = MimeApps::read()?;

    if all {
        println!("Default Apps");
    }

    let rows: Vec<(String, String)> = mimeapps.default_applications
        .iter()
        .map(|(mime, handlers)| (mime.clone(), handlers.join(", ")))
        .collect();

    render_table(&rows);

    if all {
        println!("System Apps");
        // Scan all .desktop files and group by mime type
        let entries = all_desktop_files();
        let mut system_map: Vec<(String, Vec<String>)> = Vec::new();

        for entry in &entries {
            for mime in &entry.mime_types {
                if let Some(existing) = system_map.iter_mut().find(|(m, _)| m == mime) {
                    existing.1.push(entry.file_name.clone());
                } else {
                    system_map.push((mime.clone(), vec![entry.file_name.clone()]));
                }
            }
        }

        system_map.sort_by(|a, b| a.0.cmp(&b.0));

        let rows: Vec<(String, String)> = system_map
            .iter()
            .map(|(mime, handlers)| (mime.clone(), handlers.join(", ")))
            .collect();

        render_table(&rows);
    }

    Ok(())
}

fn cmd_get(mime_arg: &str, json: bool) -> Result<()> {
    // Validate/resolve the mime type
    let mime = match resolve_mime(mime_arg) {
        Ok(m) => m,
        Err(e) => {
            eprintln!("error: Invalid value for '<mime>': {}", e);
            eprintln!("");
            eprintln!("For more information try --help");
            std::process::exit(2);
        }
    };

    let mime_str = mime.as_str();
    let mimeapps = MimeApps::read()?;

    if let Some(handlers) = mimeapps.get_default(&mime_str) {
        if let Some(first) = handlers.first() {
            if json {
                // Find the desktop file and output JSON
                let de = find_desktop_file(first)
                    .ok_or_else(|| HandlrError::Io(io::Error::new(io::ErrorKind::NotFound, "No such file or directory")))?;

                if de.terminal {
                    return Err(HandlrError::Io(io::Error::new(io::ErrorKind::NotFound, "No such file or directory")));
                }

                let cmd = exec_to_cmd_str(&de.exec);
                let json_output = format!("{{\"handler\":\"{}\",\"name\":\"{}\",\"cmd\":\"{}\"}}",
                    first, de.name, cmd);
                println!("{}", json_output);
            } else {
                println!("{}", first);
            }
            return Ok(());
        }
    }

    Err(HandlrError::Io(io::Error::new(io::ErrorKind::NotFound, "No such file or directory")))
}

fn cmd_set(mime_arg: &str, handler: &str) -> Result<()> {
    // Validate mime type
    let mime = match resolve_mime(mime_arg) {
        Ok(m) => m,
        Err(e) => {
            eprintln!("error: Invalid value for '<mime>': {}", e);
            eprintln!("");
            eprintln!("For more information try --help");
            std::process::exit(2);
        }
    };

    // Validate handler
    if !validate_handler(handler) {
        eprintln!("error: Invalid value for '<handler>': no handlers found for '{}'", handler);
        eprintln!("");
        eprintln!("For more information try --help");
        std::process::exit(2);
    }

    let mut mimeapps = MimeApps::read()?;
    mimeapps.set_default(&mime.as_str(), handler);
    mimeapps.write()?;

    Ok(())
}

fn cmd_add(mime_arg: &str, handler: &str) -> Result<()> {
    // Validate mime type
    let mime = match resolve_mime(mime_arg) {
        Ok(m) => m,
        Err(e) => {
            eprintln!("error: Invalid value for '<mime>': {}", e);
            eprintln!("");
            eprintln!("For more information try --help");
            std::process::exit(2);
        }
    };

    // Validate handler
    if !validate_handler(handler) {
        eprintln!("error: Invalid value for '<handler>': no handlers found for '{}'", handler);
        eprintln!("");
        eprintln!("For more information try --help");
        std::process::exit(2);
    }

    let mut mimeapps = MimeApps::read()?;
    mimeapps.add_handler(&mime.as_str(), handler);
    mimeapps.write()?;

    Ok(())
}

fn cmd_unset(mime_arg: &str) -> Result<()> {
    let mime = match resolve_mime(mime_arg) {
        Ok(m) => m,
        Err(e) => {
            eprintln!("error: Invalid value for '<mime>': {}", e);
            eprintln!("");
            eprintln!("For more information try --help");
            std::process::exit(2);
        }
    };

    let mut mimeapps = MimeApps::read()?;
    mimeapps.unset(&mime.as_str());
    mimeapps.write()?;

    Ok(())
}

fn launch_handler(handler: &str, args: &[String]) -> Result<()> {
    let de = find_desktop_file(handler)
        .ok_or_else(|| HandlrError::Io(io::Error::new(io::ErrorKind::NotFound, "No such file or directory")))?;

    if de.terminal {
        // Try to find a terminal emulator
        return Err(HandlrError::Io(io::Error::new(io::ErrorKind::NotFound, "No such file or directory")));
    }

    // Parse exec string and substitute field codes
    let (mut cmd_parts, _has_field_code) = parse_exec(&de.exec);

    // Add the arguments
    cmd_parts.extend(args.iter().cloned());

    if cmd_parts.is_empty() {
        return Err(HandlrError::Other("Empty exec command".to_string()));
    }

    let status = Command::new(&cmd_parts[0])
        .args(&cmd_parts[1..])
        .spawn()
        .map_err(|e| HandlrError::Io(e))?
        .wait()
        .map_err(|e| HandlrError::Io(e))?;

    Ok(())
}

fn cmd_launch(mime_arg: &str, args: &[String]) -> Result<()> {
    let mime = match resolve_mime(mime_arg) {
        Ok(m) => m,
        Err(e) => {
            eprintln!("error: Invalid value for '<mime>': {}", e);
            eprintln!("");
            eprintln!("For more information try --help");
            std::process::exit(2);
        }
    };

    let mime_str = mime.as_str();
    let mimeapps = MimeApps::read()?;

    let handlers = mimeapps.get_default(&mime_str)
        .ok_or_else(|| HandlrError::Io(io::Error::new(io::ErrorKind::NotFound, "No such file or directory")))?;

    let handler = handlers.first()
        .ok_or_else(|| HandlrError::Io(io::Error::new(io::ErrorKind::NotFound, "No such file or directory")))?;

    launch_handler(handler, args)
}

fn cmd_open(paths: &[String]) -> Result<()> {
    let mimeapps = MimeApps::read()?;

    // Group paths by mime type
    let mut mime_to_paths: Vec<(String, Vec<String>)> = Vec::new();

    for path in paths {
        // Detect mime type
        let mime = if let Some(scheme) = get_url_scheme(path) {
            format!("x-scheme-handler/{}", scheme)
        } else {
            detect_mime_from_path(path)
                .ok_or_else(|| HandlrError::Io(io::Error::new(io::ErrorKind::NotFound, "No such file or directory")))?
                .as_str()
        };

        // Find existing group
        let mut found = false;
        for (m, ps) in &mut mime_to_paths {
            if m == &mime {
                ps.push(path.clone());
                found = true;
                break;
            }
        }
        if !found {
            mime_to_paths.push((mime, vec![path.clone()]));
        }
    }

    for (mime, paths) in &mime_to_paths {
        let handlers = mimeapps.get_default(mime)
            .ok_or_else(|| HandlrError::Io(io::Error::new(io::ErrorKind::NotFound, "No such file or directory")))?;

        let handler = handlers.first()
            .ok_or_else(|| HandlrError::Io(io::Error::new(io::ErrorKind::NotFound, "No such file or directory")))?;

        launch_handler(handler, paths)?;
    }

    Ok(())
}

