fn print_help() {
    println!("handlr 0.6.4");
    println!();
    println!("USAGE:");
    println!("    {} <SUBCOMMAND>", env::args().next().unwrap_or_else(|| "executable".to_string()));
    println!();
    println!("FLAGS:");
    println!("    -h, --help       Prints help information");
    println!("    -V, --version    Prints version information");
    println!();
    println!("SUBCOMMANDS:");
    println!("    list      List default apps and the associated handlers");
    println!("    open      Open a path/URL with its default handler");
    println!("    set       Set the default handler for mime/extension");
    println!("    unset     Unset the default handler for mime/extension");
    println!("    launch    Launch the handler for specified extension/mime with optional arguments");
    println!("    get       Get handler for this mime/extension");
    println!("    add       Add a handler for given mime/extension Note that the first handler is the default");
}

fn main() {
    let args: Vec<String> = env::args().collect();

    if args.len() < 2 {
        print_help();
        return;
    }

    let result = match args[1].as_str() {
        "--help" | "-h" => {
            print_help();
            return;
        }
        "--version" | "-V" => {
            println!("handlr 0.6.4");
            return;
        }
        "list" => {
            let all = args.iter().any(|a| a == "--all" || a == "-a");
            if args.iter().any(|a| a == "--help" || a == "-h") {
                println!("executable-list ");
                println!("List default apps and the associated handlers");
                println!();
                println!("USAGE:");
                println!("    executable list [FLAGS]");
                println!();
                println!("FLAGS:");
                println!("    -a, --all        ");
                println!("    -h, --help       Prints help information");
                println!("    -V, --version    Prints version information");
                return;
            }
            cmd_list(all)
        }
        "get" => {
            if args.iter().any(|a| a == "--help" || a == "-h") {
                println!("executable-get ");
                println!("Get handler for this mime/extension");
                println!();
                println!("USAGE:");
                println!("    executable get [FLAGS] <mime>");
                println!();
                println!("ARGS:");
                println!("    <mime>    ");
                println!();
                println!("FLAGS:");
                println!("        --json       ");
                println!("    -h, --help       Prints help information");
                println!("    -V, --version    Prints version information");
                return;
            }
            let json = args.iter().any(|a| a == "--json");
            let mime_arg = args.iter()
                .skip(2)
                .find(|a| !a.starts_with('-'))
                .cloned()
                .unwrap_or_default();

            if mime_arg.is_empty() {
                eprintln!("error: The argument '<mime>' requires a value but none was supplied");
                eprintln!();
                eprintln!("USAGE:");
                eprintln!("    executable get [FLAGS] <mime>");
                eprintln!();
                eprintln!("For more information try --help");
                std::process::exit(2);
            }

            cmd_get(&mime_arg, json)
        }
        "set" => {
            if args.iter().any(|a| a == "--help" || a == "-h") {
                println!("executable-set ");
                println!("Set the default handler for mime/extension");
                println!();
                println!("USAGE:");
                println!("    executable set <mime> <handler>");
                println!();
                println!("ARGS:");
                println!("    <mime>       ");
                println!("    <handler>    ");
                println!();
                println!("FLAGS:");
                println!("    -h, --help       Prints help information");
                println!("    -V, --version    Prints version information");
                return;
            }

            let non_flag_args: Vec<&str> = args[2..].iter()
                .filter(|a| !a.starts_with('-'))
                .map(|a| a.as_str())
                .collect();

            if non_flag_args.len() < 2 {
                eprintln!("error: The following required arguments were not provided:");
                if non_flag_args.is_empty() {
                    eprintln!("    <mime>");
                }
                eprintln!("    <handler>");
                eprintln!();
                eprintln!("USAGE:");
                eprintln!("    executable set <mime> <handler>");
                eprintln!();
                eprintln!("For more information try --help");
                std::process::exit(2);
            }

            cmd_set(non_flag_args[0], non_flag_args[1])
        }
        "add" => {
            if args.iter().any(|a| a == "--help" || a == "-h") {
                println!("executable-add ");
