                eprintln!();
                eprintln!("USAGE:");
                eprintln!("    executable add <mime> <handler>");
                eprintln!();
                eprintln!("For more information try --help");
                std::process::exit(2);
            }

            cmd_add(non_flag_args[0], non_flag_args[1])
        }
        "unset" => {
            if args.iter().any(|a| a == "--help" || a == "-h") {
                println!("executable-unset ");
                println!("Unset the default handler for mime/extension");
                println!();
                println!("USAGE:");
                println!("    executable unset <mime>");
