fn launch_handler(handler: &str, args: &[String]) -> Result<()> {
    let de = find_desktop_file(handler)
        .ok_or_else(|| HandlrError::Io(io::Error::new(io::ErrorKind::NotFound, "No such file or directory")))?;

    if de.terminal {
        // Try to find a terminal emulator
        return Err(HandlrError::Io(io::Error::new(io::ErrorKind::NotFound, "No such file or directory")));
    }

    // Parse exec string and substitute field codes
    let (mut cmd_parts, _has_field_code) = parse_exec(&de.exec);

    // Add the arguments
    cmd_parts.extend(args.iter().cloned());

    if cmd_parts.is_empty() {
        return Err(HandlrError::Other("Empty exec command".to_string()));
    }

    let status = Command::new(&cmd_parts[0])
        .args(&cmd_parts[1..])
        .spawn()
        .map_err(|e| HandlrError::Io(e))?
        .wait()
        .map_err(|e| HandlrError::Io(e))?;

    Ok(())
}

fn cmd_launch(mime_arg: &str, args: &[String]) -> Result<()> {
