    let mime_str = mime.as_str();
    let mimeapps = MimeApps::read()?;

    let handlers = mimeapps.get_default(&mime_str)
        .ok_or_else(|| HandlrError::Io(io::Error::new(io::ErrorKind::NotFound, "No such file or directory")))?;

    let handler = handlers.first()
        .ok_or_else(|| HandlrError::Io(io::Error::new(io::ErrorKind::NotFound, "No such file or directory")))?;

    launch_handler(handler, args)
}

fn cmd_open(paths: &[String]) -> Result<()> {
    let mimeapps = MimeApps::read()?;

    // Group paths by mime type
    let mut mime_to_paths: Vec<(String, Vec<String>)> = Vec::new();

    for path in paths {
        // Detect mime type
        let mime = if let Some(scheme) = get_url_scheme(path) {
            format!("x-scheme-handler/{}", scheme)
        } else {
            detect_mime_from_path(path)
                .ok_or_else(|| HandlrError::Io(io::Error::new(io::ErrorKind::NotFound, "No such file or directory")))?
                .as_str()
        };

        // Find existing group
        let mut found = false;
        for (m, ps) in &mut mime_to_paths {
            if m == &mime {
                ps.push(path.clone());
                found = true;
                break;
            }
        }
        if !found {
            mime_to_paths.push((mime, vec![path.clone()]));
        }
    }

    for (mime, paths) in &mime_to_paths {
        let handlers = mimeapps.get_default(mime)
            .ok_or_else(|| HandlrError::Io(io::Error::new(io::ErrorKind::NotFound, "No such file or directory")))?;

        let handler = handlers.first()
            .ok_or_else(|| HandlrError::Io(io::Error::new(io::ErrorKind::NotFound, "No such file or directory")))?;

        launch_handler(handler, paths)?;
    }

    Ok(())
}

