/// Parse exec string and return command parts, with %f/%F/%u/%U removed
/// Returns the args list (without field codes)
fn parse_exec_no_fields(exec: &str) -> Vec<String> {
    let mut args = Vec::new();
    let mut current = String::new();
    let mut in_quotes = false;

    let chars: Vec<char> = exec.chars().collect();
    let mut i = 0;

    while i < chars.len() {
        let c = chars[i];

        if c == '"' {
            in_quotes = !in_quotes;
        } else if c == ' ' && !in_quotes {
            if !current.is_empty() {
                args.push(current.clone());
                current.clear();
            }
        } else if c == '%' && i + 1 < chars.len() {
            let next = chars[i + 1];
            match next {
                'f' | 'F' | 'u' | 'U' => {
                    // Skip field code
                    i += 1;
                }
                '%' => {
                    current.push('%');
                    i += 1;
                }
                _ => {
                    current.push(c);
                }
            }
        } else {
            current.push(c);
        }

        i += 1;
    }

    if !current.is_empty() {
        args.push(current);
    }

    args.retain(|a| !a.is_empty());
    args
}

/// Parse exec string and return command parts, substituting %f/%F/%u/%U with args
fn parse_exec_with_args(exec: &str, args: &[String]) -> Vec<String> {
    let mut parts = Vec::new();
    let mut current = String::new();
    let mut in_quotes = false;

    let chars: Vec<char> = exec.chars().collect();
    let mut i = 0;

    while i < chars.len() {
        let c = chars[i];

        if c == '"' {
            in_quotes = !in_quotes;
        } else if c == ' ' && !in_quotes {
            if !current.is_empty() {
                parts.push(current.clone());
                current.clear();
            }
        } else if c == '%' && i + 1 < chars.len() {
            let next = chars[i + 1];
            match next {
                'f' | 'u' => {
                    // Single file/URL - add each arg as separate command execution
                    // For simplicity, add all args here
                    if !current.is_empty() {
                        parts.push(current.clone());
                        current.clear();
                    }
                    for arg in args {
                        parts.push(arg.clone());
                    }
                    i += 1;
                }
                'F' | 'U' => {
                    // Multiple files/URLs
                    if !current.is_empty() {
                        parts.push(current.clone());
                        current.clear();
                    }
                    for arg in args {
                        parts.push(arg.clone());
                    }
                    i += 1;
                }
                '%' => {
                    current.push('%');
                    i += 1;
                }
                _ => {
                    current.push(c);
                }
            }
        } else {
            current.push(c);
        }

        i += 1;
    }

    if !current.is_empty() {
        parts.push(current);
    }

    parts.retain(|p| !p.is_empty());
    parts
}

/// Build the command string for JSON output (without the file argument)
fn exec_to_cmd_str(exec: &str) -> String {
    let mut parts: Vec<String> = Vec::new();
    let mut current = String::new();
    let mut in_quotes = false;
    let mut has_field_code = false;

    let chars: Vec<char> = exec.chars().collect();
    let mut i = 0;

    while i < chars.len() {
        let c = chars[i];

        if c == '"' {
            in_quotes = !in_quotes;
        } else if c == ' ' && !in_quotes {
            if !current.is_empty() {
                parts.push(current.clone());
                current.clear();
            }
        } else if c == '%' && i + 1 < chars.len() {
            let next = chars[i + 1];
            match next {
                'f' | 'F' | 'u' | 'U' => {
                    has_field_code = true;
                    // Don't add to parts
                    i += 1;
                }
                '%' => {
                    current.push('%');
                    i += 1;
                }
                _ => {
                    current.push(c);
                }
            }
        } else {
            current.push(c);
        }

        i += 1;
    }

    if !current.is_empty() {
        parts.push(current);
    }

    parts.retain(|p| !p.is_empty());

    let cmd = parts.join(" ");
    if has_field_code {
        cmd + " "
    } else {
        cmd
    }
}

// ─── Table rendering ──────────────────────────────────────────────────────────

fn render_table(rows: &[(String, String)]) {
    if rows.is_empty() {
        println!("┌──┐");
        println!("│  │");
        println!("└──┘");
        return;
    }

    let max_col1 = rows.iter().map(|(k, _)| k.chars().count()).max().unwrap_or(0);
    let max_col2 = rows.iter().map(|(_, v)| v.chars().count()).max().unwrap_or(0);

    let col1_inner = max_col1 + 2; // content + 2 spaces padding
    let col2_inner = max_col2 + 2; // content + 2 spaces padding

    // Total = 2 borders (│...│...│) = 1 + col1_inner + 1 + col2_inner + 1
    let total_width = 1 + col1_inner + 1 + col2_inner + 1;

    let (col1_display, col2_display) = if total_width <= 80 {
        (col1_inner, col2_inner)
    } else {
        // Need to cap at 80
        let available_for_col2 = 80 - 1 - col1_inner - 1 - 1;
        (col1_inner, available_for_col2)
    };

    let col2_content_max = col2_display - 2; // content width (subtract 2 for padding)

    // Print top border
    let col1_dashes = "─".repeat(col1_display);
    let col2_dashes = "─".repeat(col2_display);
    println!("┌{}┬{}┐", col1_dashes, col2_dashes);

    // Print rows
    for (key, value) in rows {
        let key_chars_count = key.chars().count();
        let key_padding = col1_inner - 2 - key_chars_count; // padding on right
        let key_str = format!(" {}{} ", key, " ".repeat(key_padding));

        let val_chars: Vec<char> = value.chars().collect();
        let val_str = if val_chars.len() > col2_content_max {
            // Truncate with +
            let truncated: String = val_chars[..col2_content_max - 1].iter().collect();
            format!("{}+", truncated)
        } else {
            value.clone()
        };

        let val_chars_count = val_str.chars().count();
        let val_padding = col2_inner - 2 - val_chars_count;
        let actual_col2_content_width = col2_display - 2;

        // Re-pad properly
        let val_display = if val_chars.len() > col2_content_max {
            // Truncated
            format!(" {} ", val_str)
        } else {
            let padding = actual_col2_content_width - val_chars_count;
            format!(" {}{} ", val_str, " ".repeat(padding))
        };

        println!("│{}│{}│", key_str, val_display);
    }

    // Print bottom border
    println!("└{}┴{}┘", col1_dashes, col2_dashes);
}

// ─── Command handlers ─────────────────────────────────────────────────────────

fn cmd_list(all: bool) -> Result<()> {
    let mimeapps = MimeApps::read()?;

    if all {
        println!("Default Apps");
    }

    let rows: Vec<(String, String)> = mimeapps.default_applications
        .iter()
        .map(|(mime, handlers)| (mime.clone(), handlers.join(", ")))
        .collect();

    render_table(&rows);

    if all {
        println!("System Apps");
        // Scan all .desktop files and group by mime type
        let entries = all_desktop_files();
        let mut system_map: Vec<(String, Vec<String>)> = Vec::new();

        for entry in &entries {
            for mime in &entry.mime_types {
                if let Some(existing) = system_map.iter_mut().find(|(m, _)| m == mime) {
                    existing.1.push(entry.file_name.clone());
                } else {
                    system_map.push((mime.clone(), vec![entry.file_name.clone()]));
                }
            }
        }

        system_map.sort_by(|a, b| a.0.cmp(&b.0));

        let rows: Vec<(String, String)> = system_map
            .iter()
            .map(|(mime, handlers)| (mime.clone(), handlers.join(", ")))
            .collect();

        render_table(&rows);
    }

    Ok(())
}

fn cmd_get(mime_arg: &str, json: bool) -> Result<()> {
    let mime = match resolve_mime(mime_arg) {
        Ok(m) => m,
        Err(e) => {
            eprintln!("error: Invalid value for '<mime>': {}", e);
            eprintln!("");
            eprintln!("For more information try --help");
            std::process::exit(2);
        }
    };

    let mime_str = mime.as_str();
    let mimeapps = MimeApps::read()?;

    if let Some(handlers) = mimeapps.get_default(&mime_str) {
        if let Some(first) = handlers.first() {
            if json {
                let de = find_desktop_file(first)
                    .ok_or_else(|| not_found_error())?;

                if de.terminal {
                    return Err(not_found_error());
                }

                let cmd = exec_to_cmd_str(&de.exec);
                println!("{{\"handler\":\"{}\",\"name\":\"{}\",\"cmd\":\"{}\"}}", first, de.name, cmd);
            } else {
                println!("{}", first);
            }
            return Ok(());
        }
    }

    Err(not_found_error())
}

fn cmd_set(mime_arg: &str, handler: &str) -> Result<()> {
    let mime = match resolve_mime(mime_arg) {
        Ok(m) => m,
        Err(e) => {
