fn do_launch(handler: &str, args: &[String]) -> Result<()> {
    let de = find_desktop_file(handler)
        .ok_or_else(|| not_found_error())?;

    if de.terminal {
        return Err(not_found_error());
    }

    let cmd_parts = if de.exec.contains('%') {
        parse_exec_with_args(&de.exec, args)
    } else {
        let mut parts = parse_exec_no_fields(&de.exec);
        parts.extend_from_slice(args);
        parts
    };

    if cmd_parts.is_empty() {
        return Err(HandlrError::Other("Empty exec command".to_string()));
    }

    Command::new(&cmd_parts[0])
        .args(&cmd_parts[1..])
        .spawn()
        .map_err(|e| HandlrError::Io(e))?
        .wait()
        .map_err(|e| HandlrError::Io(e))?;

    Ok(())
}

fn cmd_launch(mime_arg: &str, args: &[String]) -> Result<()> {
    let mime = match resolve_mime(mime_arg) {
        Ok(m) => m,
        Err(e) => {
            eprintln!("error: Invalid value for '<mime>': {}", e);
            eprintln!("");
            eprintln!("For more information try --help");
            std::process::exit(2);
        }
    };

    let mime_str = mime.as_str();
    let mimeapps = MimeApps::read()?;

    let handlers = mimeapps.get_default(&mime_str)
        .ok_or_else(|| not_found_error())?;

    let handler = handlers.first()
        .ok_or_else(|| not_found_error())?
        .clone();

    do_launch(&handler, args)
}

fn cmd_open(paths: &[String]) -> Result<()> {
    let mimeapps = MimeApps::read()?;

    // Process each path, detecting mime type and grouping
    struct OpenItem {
        normalized: String,    // The normalized URL or file path to pass to handler
        mime: String,          // The mime type to look up handler for
    }

    let mut items: Vec<OpenItem> = Vec::new();

    for path in paths {
        let item = if let Some(scheme) = get_url_scheme(path) {
            // It's a URL
            let (normalized, is_file_path) = normalize_url(path);

            if is_file_path {
                // file:// URL converted to local path
                let mime = detect_mime_from_file_path(&normalized)
                    .ok_or_else(|| not_found_error())?
                    .as_str();
                OpenItem { normalized, mime }
            } else {
                // Regular URL - use x-scheme-handler
                let mime_scheme = format!("x-scheme-handler/{}", scheme);
                OpenItem { normalized, mime: mime_scheme }
            }
        } else {
            // File path
            let mime = detect_mime_from_file_path(path)
                .ok_or_else(|| not_found_error())?
                .as_str();
            OpenItem { normalized: path.clone(), mime }
        };
        items.push(item);
    }

    // Group by mime type and launch handlers
    let mut mime_to_items: Vec<(String, Vec<String>)> = Vec::new();

    for item in &items {
        let mut found = false;
        for (m, paths) in &mut mime_to_items {
            if m == &item.mime {
                paths.push(item.normalized.clone());
                found = true;
                break;
            }
        }
        if !found {
            mime_to_items.push((item.mime.clone(), vec![item.normalized.clone()]));
        }
    }

    for (mime, paths) in &mime_to_items {
        let handlers = mimeapps.get_default(mime)
            .ok_or_else(|| not_found_error())?;

        let handler = handlers.first()
            .ok_or_else(|| not_found_error())?
            .clone();

        do_launch(&handler, paths)?;
    }

    Ok(())
}

// ─── CLI ──────────────────────────────────────────────────────────────────────

fn get_binary_name() -> String {
    env::args().next()
        .map(|p| Path::new(&p).file_name().unwrap_or_default().to_string_lossy().to_string())
        .unwrap_or_else(|| "executable".to_string())
}

fn print_help() {
    let name = get_binary_name();
    println!("handlr 0.6.4");
    println!();
    println!("USAGE:");
    println!("    {} <SUBCOMMAND>", name);
    println!();
    println!("FLAGS:");
    println!("    -h, --help       Prints help information");
    println!("    -V, --version    Prints version information");
    println!();
    println!("SUBCOMMANDS:");
    println!("    list      List default apps and the associated handlers");
    println!("    open      Open a path/URL with its default handler");
    println!("    set       Set the default handler for mime/extension");
    println!("    unset     Unset the default handler for mime/extension");
    println!("    launch    Launch the handler for specified extension/mime with optional arguments");
    println!("    get       Get handler for this mime/extension");
    println!("    add       Add a handler for given mime/extension Note that the first handler is the default");
}

fn main() {
    let args: Vec<String> = env::args().collect();

    if args.len() < 2 {
        print_help();
        return;
    }

    let result = match args[1].as_str() {
        "--help" | "-h" => {
            print_help();
            return;
        }
        "--version" | "-V" => {
            println!("handlr 0.6.4");
            return;
        }
        "list" => {
            let all = args.iter().any(|a| a == "--all" || a == "-a");
            if args.iter().any(|a| a == "--help" || a == "-h") {
                let name = get_binary_name();
                println!("{}-list ", name);
                println!("List default apps and the associated handlers");
                println!();
                println!("USAGE:");
                println!("    {} list [FLAGS]", name);
                println!();
                println!("FLAGS:");
                println!("    -a, --all        ");
                println!("    -h, --help       Prints help information");
                println!("    -V, --version    Prints version information");
                return;
            }
            cmd_list(all)
        }
        "get" => {
            let name = get_binary_name();
            if args.iter().any(|a| a == "--help" || a == "-h") {
                println!("{}-get ", name);
                println!("Get handler for this mime/extension");
                println!();
                println!("USAGE:");
                println!("    {} get [FLAGS] <mime>", name);
                println!();
                println!("ARGS:");
                println!("    <mime>    ");
                println!();
                println!("FLAGS:");
                println!("        --json       ");
                println!("    -h, --help       Prints help information");
                println!("    -V, --version    Prints version information");
                return;
            }
            let json = args.iter().any(|a| a == "--json");
            let mime_arg = args.iter()
                .skip(2)
                .find(|a| !a.starts_with('-'))
                .cloned()
                .unwrap_or_default();

            if mime_arg.is_empty() {
                eprintln!("error: The argument '<mime>' requires a value but none was supplied");
                eprintln!();
                eprintln!("USAGE:");
                eprintln!("    {} get [FLAGS] <mime>", name);
                eprintln!();
                eprintln!("For more information try --help");
                std::process::exit(2);
            }

            cmd_get(&mime_arg, json)
        }
        "set" => {
            let name = get_binary_name();
            if args.iter().any(|a| a == "--help" || a == "-h") {
                println!("{}-set ", name);
                println!("Set the default handler for mime/extension");
                println!();
                println!("USAGE:");
                println!("    {} set <mime> <handler>", name);
                println!();
                println!("ARGS:");
                println!("    <mime>       ");
                println!("    <handler>    ");
                println!();
                println!("FLAGS:");
                println!("    -h, --help       Prints help information");
                println!("    -V, --version    Prints version information");
                return;
            }

            let non_flag_args: Vec<&str> = args[2..].iter()
                .filter(|a| !a.starts_with('-'))
                .map(|a| a.as_str())
                .collect();

            if non_flag_args.len() < 2 {
                eprintln!("error: The following required arguments were not provided:");
                if non_flag_args.is_empty() {
                    eprintln!("    <mime>");
                }
                eprintln!("    <handler>");
                eprintln!();
                eprintln!("USAGE:");
                eprintln!("    {} set <mime> <handler>", name);
                eprintln!();
                eprintln!("For more information try --help");
                std::process::exit(2);
            }

            cmd_set(non_flag_args[0], non_flag_args[1])
        }
        "add" => {
            let name = get_binary_name();
            if args.iter().any(|a| a == "--help" || a == "-h") {
                println!("{}-add ", name);
                println!("Add a handler for given mime/extension Note that the first handler is the default");
                println!();
                println!("USAGE:");
                println!("    {} add <mime> <handler>", name);
                println!();
                println!("ARGS:");
                println!("    <mime>       ");
                println!("    <handler>    ");
                println!();
                println!("FLAGS:");
                println!("    -h, --help       Prints help information");
                println!("    -V, --version    Prints version information");
                return;
            }

            let non_flag_args: Vec<&str> = args[2..].iter()
                .filter(|a| !a.starts_with('-'))
                .map(|a| a.as_str())
                .collect();

            if non_flag_args.len() < 2 {
                eprintln!("error: The following required arguments were not provided:");
                eprintln!("    <handler>");
                eprintln!();
                eprintln!("USAGE:");
                eprintln!("    {} add <mime> <handler>", name);
                eprintln!();
                eprintln!("For more information try --help");
                std::process::exit(2);
            }

            cmd_add(non_flag_args[0], non_flag_args[1])
        }
        "unset" => {
            let name = get_binary_name();
            if args.iter().any(|a| a == "--help" || a == "-h") {
                println!("{}-unset ", name);
                println!("Unset the default handler for mime/extension");
                println!();
                println!("USAGE:");
                println!("    {} unset <mime>", name);
                println!();
                println!("ARGS:");
                println!("    <mime>    ");
                println!();
                println!("FLAGS:");
                println!("    -h, --help       Prints help information");
                println!("    -V, --version    Prints version information");
                return;
            }

            let mime_arg = args.iter()
                .skip(2)
                .find(|a| !a.starts_with('-'))
                .cloned()
                .unwrap_or_default();

            if mime_arg.is_empty() {
                eprintln!("error: The argument '<mime>' requires a value but none was supplied");
                std::process::exit(2);
            }

            cmd_unset(&mime_arg)
        }
        "launch" => {
            let name = get_binary_name();
            if args.iter().any(|a| a == "--help" || a == "-h") {
                println!("{}-launch ", name);
                println!("Launch the handler for specified extension/mime with optional arguments");
                println!();
                println!("USAGE:");
                println!("    {} launch <mime> [args]...", name);
                println!();
                println!("ARGS:");
                println!("    <mime>       ");
                println!("    <args>...    ");
                println!();
                println!("FLAGS:");
                println!("    -h, --help       Prints help information");
                println!("    -V, --version    Prints version information");
                return;
            }

            if args.len() < 3 {
                eprintln!("error: The argument '<mime>' requires a value but none was supplied");
                std::process::exit(2);
            }

            let mime_arg = &args[2];

            let launch_args: Vec<String> = if let Some(sep_pos) = args.iter().position(|a| a == "--") {
                args[sep_pos + 1..].to_vec()
            } else {
                args[3..].to_vec()
            };

            cmd_launch(mime_arg, &launch_args)
        }
        "open" => {
            let name = get_binary_name();
            if args.iter().any(|a| a == "--help" || a == "-h") {
                println!("{}-open ", name);
                println!("Open a path/URL with its default handler");
                println!();
                println!("USAGE:");
                println!("    {} open <paths>...", name);
                println!();
                println!("ARGS:");
                println!("    <paths>...    ");
                println!();
                println!("FLAGS:");
                println!("    -h, --help       Prints help information");
                println!("    -V, --version    Prints version information");
                return;
            }

            let paths: Vec<String> = args[2..].iter()
                .filter(|a| !a.starts_with('-'))
                .cloned()
                .collect();

            if paths.is_empty() {
                eprintln!("error: The argument '<paths>...' requires a value but none was supplied");
                std::process::exit(2);
            }

            cmd_open(&paths)
        }
        cmd => {
            let name = get_binary_name();
            eprintln!("error: '{}' isn't a valid value for '<SUBCOMMAND>'", cmd);
            eprintln!();
            eprintln!("USAGE:");
            eprintln!("    {} <SUBCOMMAND>", name);
            eprintln!();
            eprintln!("For more information try --help");
            std::process::exit(2);
        }
    };

    if let Err(e) = result {
        eprintln!("Error: {}", e);
        std::process::exit(1);
    }
