// ─── MIME type parsing/validation ─────────────────────────────────────────────

#[derive(Debug, Clone)]
struct MimeType {
    type_: String,
    subtype: String,
}

impl MimeType {
    fn new(type_: &str, subtype: &str) -> Self {
        MimeType {
            type_: type_.to_string(),
            subtype: subtype.to_string(),
        }
    }

    fn as_str(&self) -> String {
        format!("{}/{}", self.type_, self.subtype)
    }
}

impl std::fmt::Display for MimeType {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(f, "{}/{}", self.type_, self.subtype)
    }
}

fn parse_mime_type(s: &str) -> std::result::Result<MimeType, String> {
    if s.is_empty() {
        return Err("an invalid token was encountered, empty string".to_string());
    }

    // First char must not be '/'
    let first_char = s.chars().next().unwrap();
    if first_char == '/' {
        return Err(format!("an invalid token was encountered, 2F at position 0"));
    }

    if let Some(slash_pos) = s.find('/') {
        let type_ = &s[..slash_pos];
        let subtype = &s[slash_pos + 1..];

        if type_.is_empty() {
            return Err("a slash (/) was missing between the type and subtype".to_string());
        }

        if subtype.is_empty() {
            return Err(format!("bad mime: {}", s));
        }

        Ok(MimeType::new(type_, subtype))
    } else {
        // No slash found
        if s.starts_with('.') {
            Err(format!("could not figure out the mime type of '{}'", s))
        } else {
            Err("a slash (/) was missing between the type and subtype".to_string())
        }
    }
}

// Resolve a mime arg (could be extension like ".png" or mime type like "image/png")
fn resolve_mime(arg: &str) -> std::result::Result<MimeType, String> {
    if arg.starts_with('.') {
        match lookup_mime_from_extension(arg) {
            Some(m) => Ok(m),
            None => Err(format!("could not figure out the mime type of '{}'", arg)),
        }
    } else {
        parse_mime_type(arg)
    }
}

// ─── MIME database (globs2 file) ──────────────────────────────────────────────

fn load_mime_globs() -> HashMap<String, String> {
    let mut globs: HashMap<String, (u32, String)> = HashMap::new();

    for data_dir in xdg_data_dirs() {
        // Try globs2 first (weighted format: weight:mime:pattern)
        let globs2_path = data_dir.join("mime/globs2");
        if let Ok(content) = fs::read_to_string(&globs2_path) {
            for line in content.lines() {
                if line.starts_with('#') || line.is_empty() {
                    continue;
                }
                let parts: Vec<&str> = line.splitn(3, ':').collect();
                if parts.len() == 3 {
                    let weight: u32 = parts[0].parse().unwrap_or(50);
                    let mime = parts[1];
                    let pattern = parts[2];
                    if pattern.starts_with("*.") {
                        let ext = pattern[1..].to_lowercase();
                        let entry = globs.entry(ext).or_insert((0, String::new()));
                        if weight > entry.0 {
                            *entry = (weight, mime.to_string());
                        }
                    }
                }
            }
        }

        // Also try globs file (format: mime:pattern)
        let globs_path = data_dir.join("mime/globs");
        if let Ok(content) = fs::read_to_string(&globs_path) {
            for line in content.lines() {
                if line.starts_with('#') || line.is_empty() {
                    continue;
                }
                let parts: Vec<&str> = line.splitn(2, ':').collect();
                if parts.len() == 2 {
                    let mime = parts[0];
                    let pattern = parts[1];
                    if pattern.starts_with("*.") {
                        let ext = pattern[1..].to_lowercase();
                        globs.entry(ext).or_insert((50, mime.to_string()));
                    }
                }
            }
        }
    }

    globs.into_iter().map(|(k, (_, v))| (k, v)).collect()
}

fn lookup_mime_from_extension(ext: &str) -> Option<MimeType> {
    let ext_lower = ext.to_lowercase();
    let globs = load_mime_globs();

    if let Some(mime_str) = globs.get(&ext_lower) {
        if let Ok(m) = parse_mime_type(mime_str) {
            return Some(m);
        }
    }
    None
}

// ─── URL parsing/normalization ────────────────────────────────────────────────

/// Special URL schemes that are treated as hierarchical (path-based)
/// These are the "special" schemes in the WHATWG URL standard
const SPECIAL_SCHEMES: &[&str] = &["ftp", "file", "http", "https", "ws", "wss"];

/// Returns the URL scheme if the string looks like a URL
fn get_url_scheme(s: &str) -> Option<String> {
    if let Some(colon_pos) = s.find(':') {
        if colon_pos > 0 {
            let scheme = &s[..colon_pos];
            // Validate: scheme should be letters, digits, +, -, .
            // and must start with a letter
            if scheme.chars().next().map(|c| c.is_ascii_alphabetic()).unwrap_or(false) 
                && scheme.chars().all(|c| c.is_ascii_alphanumeric() || c == '+' || c == '-' || c == '.') 
            {
                return Some(scheme.to_lowercase());
            }
        }
    }
    None
}

/// Normalize a URL:
/// - For "file" scheme: extract the local path
/// - For special hierarchical schemes (http, https, ftp, ws, wss): add trailing slash if empty path
/// - For other schemes: return as-is
/// Returns (normalized_url, is_file_path) where is_file_path=true means we should use file detection
fn normalize_url(url: &str) -> (String, bool) {
    let scheme = match get_url_scheme(url) {
        Some(s) => s,
        None => return (url.to_string(), false),
    };

    // File URL: extract local path
    if scheme == "file" {
        // file:///path -> /path
        // file://localhost/path -> /path
        // file://host/path -> //host/path (not typical, but handle gracefully)
        let rest = &url[5..]; // After "file:"
        if rest.starts_with("///") {
            // file:///path -> /path
            return (rest[2..].to_string(), true);
        } else if rest.starts_with("//localhost/") || rest.starts_with("//LOCALHOST/") {
            return (rest["//localhost".len()..].to_string(), true);
        } else if rest.starts_with("//") {
            // file://host/path - treat as file path
            let after_slashes = &rest[2..];
            if let Some(slash_pos) = after_slashes.find('/') {
                return (after_slashes[slash_pos..].to_string(), true);
            }
        }
        return (url.to_string(), true);
    }

    // For special hierarchical schemes, normalize by adding trailing slash if needed
    if SPECIAL_SCHEMES.contains(&scheme.as_str()) {
        // Parse the URL to check if it needs a trailing slash
        let normalized = normalize_hierarchical_url(url, &scheme);
        return (normalized, false);
    }

    // For other schemes, return as-is
    (url.to_string(), false)
}

/// Normalize a hierarchical URL (like http, https, ftp) by adding trailing slash
/// when the path is empty
fn normalize_hierarchical_url(url: &str, scheme: &str) -> String {
    // Format: scheme://[user:pass@]host[:port][/path][?query][#fragment]
    let scheme_prefix = format!("{}://", scheme);
    let rest = &url[scheme_prefix.len()..];

    // Find where the authority ends (start of path, query, or fragment)
    // Authority ends at the first '/', '?', or '#'
    // But we need to handle empty path - if none of these chars exist, path is empty

    let path_start = rest.find(|c| c == '/' || c == '?' || c == '#');

    match path_start {
        None => {
            // No path, query, or fragment - add trailing slash
            format!("{}{}/", scheme_prefix, rest)
        }
        Some(pos) => {
            let ch = rest.chars().nth(pos).unwrap();
            if ch == '/' {
                // Has a path - no modification needed
                url.to_string()
            } else {
                // Starts with ? or # - insert / before
                format!("{}{}/{}", scheme_prefix, &rest[..pos], &rest[pos..])
            }
        }
    }
}

/// Detect mime type from a file path
fn detect_mime_from_file_path(path: &str) -> Option<MimeType> {
    let p = Path::new(path);
    if let Some(ext) = p.extension() {
        let ext_str = format!(".{}", ext.to_string_lossy().to_lowercase());
        return lookup_mime_from_extension(&ext_str);
    }
    None
}

// ─── mimeapps.list reading/writing ────────────────────────────────────────────

#[derive(Debug, Default)]
struct MimeApps {
    added_associations: Vec<(String, Vec<String>)>,
    default_applications: Vec<(String, Vec<String>)>,
}

impl MimeApps {
    fn read() -> Result<Self> {
        let path = mimeapps_list_path();
        if !path.exists() {
            return Ok(MimeApps::default());
        }
        let content = fs::read_to_string(&path)?;
        Self::parse(&content)
    }

    fn parse(content: &str) -> Result<Self> {
        let mut mimeapps = MimeApps::default();
        let mut section = "";

        for line in content.lines() {
            let line = line.trim();
            if line.is_empty() || line.starts_with('#') {
                continue;
            }
            if line == "[Added Associations]" {
                section = "added";
                continue;
            }
            if line == "[Default Applications]" {
                section = "default";
                continue;
            }
            if line.starts_with('[') {
                section = "other";
                continue;
            }

            if let Some(eq_pos) = line.find('=') {
                let mime = line[..eq_pos].trim().to_string();
                let handlers_str = line[eq_pos + 1..].trim();
                let handlers: Vec<String> = handlers_str
                    .split(';')
                    .filter(|s| !s.is_empty())
                    .map(|s| s.trim().to_string())
                    .collect();

                match section {
                    "added" => mimeapps.added_associations.push((mime, handlers)),
                    "default" => mimeapps.default_applications.push((mime, handlers)),
                    _ => {}
                }
            }
        }

        Ok(mimeapps)
    }

    fn write(&self) -> Result<()> {
        let path = mimeapps_list_path();
        if let Some(parent) = path.parent() {
            fs::create_dir_all(parent)?;
        }
        let mut content = String::new();
        content.push_str("[Added Associations]\n");
        for (mime, handlers) in &self.added_associations {
            content.push_str(mime);
            content.push('=');
            content.push_str(&handlers.join(";"));
            content.push_str(";\n");
        }
        content.push('\n');
        content.push_str("[Default Applications]\n");
        for (mime, handlers) in &self.default_applications {
            content.push_str(mime);
            content.push('=');
            content.push_str(&handlers.join(";"));
            content.push_str(";\n");
        }
        fs::write(&path, content)?;
        Ok(())
    }

    fn get_default(&self, mime: &str) -> Option<&Vec<String>> {
        // First try exact match
        for (m, handlers) in &self.default_applications {
            if m == mime {
                return Some(handlers);
            }
        }
        // Then try wildcard match (e.g., "text/*")
        if let Some(slash_pos) = mime.find('/') {
            let type_ = &mime[..slash_pos];
            let wildcard = format!("{}/*", type_);
            for (m, handlers) in &self.default_applications {
                if m == &wildcard {
                    return Some(handlers);
                }
            }
        }
        None
    }

    fn set_default(&mut self, mime: &str, handler: &str) {
        for entry in &mut self.default_applications {
            if entry.0 == mime {
                entry.1 = vec![handler.to_string()];
                return;
            }
        }
        self.default_applications.push((mime.to_string(), vec![handler.to_string()]));
        self.default_applications.sort_by(|a, b| a.0.cmp(&b.0));
    }

    fn add_handler(&mut self, mime: &str, handler: &str) {
        for entry in &mut self.default_applications {
            if entry.0 == mime {
                entry.1.push(handler.to_string());
                return;
            }
        }
        self.default_applications.push((mime.to_string(), vec![handler.to_string()]));
        self.default_applications.sort_by(|a, b| a.0.cmp(&b.0));
    }

    fn unset(&mut self, mime: &str) {
        self.default_applications.retain(|e| e.0 != mime);
    }
}

// ─── Desktop file parsing ──────────────────────────────────────────────────────

#[derive(Debug, Clone)]
struct DesktopEntry {
    name: String,
    exec: String,
    terminal: bool,
    mime_types: Vec<String>,
    file_name: String,
}

fn parse_desktop_file(path: &Path) -> Option<DesktopEntry> {
    let content = fs::read_to_string(path).ok()?;
    let mut name = None;
    let mut exec = None;
    let mut terminal = false;
    let mut mime_types = Vec::new();
    let mut in_desktop_entry = false;

    for line in content.lines() {
        let line = line.trim();
        if line == "[Desktop Entry]" {
            in_desktop_entry = true;
            continue;
        }
        if line.starts_with('[') {
            in_desktop_entry = false;
            continue;
        }
        if !in_desktop_entry {
            continue;
        }
        if line.is_empty() || line.starts_with('#') {
            continue;
        }

        if let Some(eq_pos) = line.find('=') {
            let key = line[..eq_pos].trim();
            let value = line[eq_pos + 1..].trim();
            match key {
                "Name" => { name = Some(value.to_string()); }
                "Exec" => { exec = Some(value.to_string()); }
                "Terminal" => { terminal = value.eq_ignore_ascii_case("true"); }
                "MimeType" => {
                    mime_types = value.split(';')
                        .filter(|s| !s.is_empty())
                        .map(|s| s.to_string())
                        .collect();
                }
                _ => {}
            }
        }
    }

    let file_name = path.file_name()?.to_string_lossy().to_string();

    Some(DesktopEntry {
        name: name?,
        exec: exec?,
        terminal,
        mime_types,
        file_name,
    })
}

fn find_desktop_file(name: &str) -> Option<DesktopEntry> {
    for data_dir in xdg_data_dirs() {
        let path = data_dir.join("applications").join(name);
        if path.exists() {
            return parse_desktop_file(&path);
        }
    }
    None
}

fn validate_handler(name: &str) -> bool {
    find_desktop_file(name).is_some()
}

fn all_desktop_files() -> Vec<DesktopEntry> {
    let mut entries = Vec::new();
    let mut seen = std::collections::HashSet::new();

    for data_dir in xdg_data_dirs() {
        let apps_dir = data_dir.join("applications");
        if let Ok(read_dir) = fs::read_dir(&apps_dir) {
            let mut files: Vec<_> = read_dir
                .filter_map(|e| e.ok())
                .filter(|e| {
                    e.path().extension()
                        .map(|x| x == "desktop")
                        .unwrap_or(false)
                })
                .collect();
            files.sort_by_key(|e| e.file_name());

            for entry in files {
                let path = entry.path();
                let file_name = path.file_name().unwrap().to_string_lossy().to_string();
                if seen.contains(&file_name) {
                    continue;
                }
                if let Some(de) = parse_desktop_file(&path) {
                    seen.insert(file_name);
                    entries.push(de);
                }
            }
        }
    }
    entries
}

// ─── Exec parsing ─────────────────────────────────────────────────────────────

/// Parse exec string and return command parts, with %f/%F/%u/%U removed
/// Returns the args list (without field codes)
fn parse_exec_no_fields(exec: &str) -> Vec<String> {
    let mut args = Vec::new();
    let mut current = String::new();
    let mut in_quotes = false;

    let chars: Vec<char> = exec.chars().collect();
    let mut i = 0;

    while i < chars.len() {
        let c = chars[i];

        if c == '"' {
            in_quotes = !in_quotes;
        } else if c == ' ' && !in_quotes {
            if !current.is_empty() {
                args.push(current.clone());
                current.clear();
            }
        } else if c == '%' && i + 1 < chars.len() {
            let next = chars[i + 1];
            match next {
                'f' | 'F' | 'u' | 'U' => {
                    // Skip field code
                    i += 1;
                }
                '%' => {
                    current.push('%');
                    i += 1;
                }
                _ => {
                    current.push(c);
                }
            }
        } else {
            current.push(c);
        }

        i += 1;
    }

    if !current.is_empty() {
        args.push(current);
    }

    args.retain(|a| !a.is_empty());
    args
}

/// Parse exec string and return command parts, substituting %f/%F/%u/%U with args
fn parse_exec_with_args(exec: &str, args: &[String]) -> Vec<String> {
    let mut parts = Vec::new();
    let mut current = String::new();
    let mut in_quotes = false;

    let chars: Vec<char> = exec.chars().collect();
    let mut i = 0;

    while i < chars.len() {
        let c = chars[i];

        if c == '"' {
            in_quotes = !in_quotes;
        } else if c == ' ' && !in_quotes {
            if !current.is_empty() {
                parts.push(current.clone());
                current.clear();
            }
        } else if c == '%' && i + 1 < chars.len() {
            let next = chars[i + 1];
            match next {
                'f' | 'u' => {
                    // Single file/URL - add each arg as separate command execution
                    // For simplicity, add all args here
                    if !current.is_empty() {
                        parts.push(current.clone());
                        current.clear();
                    }
                    for arg in args {
                        parts.push(arg.clone());
                    }
                    i += 1;
                }
                'F' | 'U' => {
                    // Multiple files/URLs
                    if !current.is_empty() {
                        parts.push(current.clone());
                        current.clear();
                    }
                    for arg in args {
                        parts.push(arg.clone());
                    }
                    i += 1;
                }
                '%' => {
                    current.push('%');
                    i += 1;
                }
                _ => {
                    current.push(c);
                }
            }
        } else {
            current.push(c);
        }

        i += 1;
    }

    if !current.is_empty() {
        parts.push(current);
    }

    parts.retain(|p| !p.is_empty());
    parts
}

/// Build the command string for JSON output (without the file argument)
fn exec_to_cmd_str(exec: &str) -> String {
    let mut parts: Vec<String> = Vec::new();
    let mut current = String::new();
    let mut in_quotes = false;
    let mut has_field_code = false;

    let chars: Vec<char> = exec.chars().collect();
    let mut i = 0;

    while i < chars.len() {
        let c = chars[i];

        if c == '"' {
            in_quotes = !in_quotes;
        } else if c == ' ' && !in_quotes {
            if !current.is_empty() {
                parts.push(current.clone());
                current.clear();
            }
        } else if c == '%' && i + 1 < chars.len() {
            let next = chars[i + 1];
            match next {
                'f' | 'F' | 'u' | 'U' => {
                    has_field_code = true;
                    // Don't add to parts
                    i += 1;
                }
                '%' => {
                    current.push('%');
                    i += 1;
                }
                _ => {
                    current.push(c);
                }
            }
        } else {
            current.push(c);
        }

        i += 1;
    }

    if !current.is_empty() {
        parts.push(current);
    }

    parts.retain(|p| !p.is_empty());

    let cmd = parts.join(" ");
    if has_field_code {
        cmd + " "
    } else {
        cmd
    }
}

// ─── Table rendering ──────────────────────────────────────────────────────────

fn render_table(rows: &[(String, String)]) {
    if rows.is_empty() {
        println!("┌──┐");
        println!("│  │");
        println!("└──┘");
        return;
    }

    let max_col1 = rows.iter().map(|(k, _)| k.chars().count()).max().unwrap_or(0);
    let max_col2 = rows.iter().map(|(_, v)| v.chars().count()).max().unwrap_or(0);

    let col1_inner = max_col1 + 2; // content + 2 spaces padding
    let col2_inner = max_col2 + 2; // content + 2 spaces padding

    // Total = 2 borders (│...│...│) = 1 + col1_inner + 1 + col2_inner + 1
    let total_width = 1 + col1_inner + 1 + col2_inner + 1;

    let (col1_display, col2_display) = if total_width <= 80 {
        (col1_inner, col2_inner)
    } else {
        // Need to cap at 80
        let available_for_col2 = 80 - 1 - col1_inner - 1 - 1;
        (col1_inner, available_for_col2)
    };

    let col2_content_max = col2_display - 2; // content width (subtract 2 for padding)

    // Print top border
    let col1_dashes = "─".repeat(col1_display);
    let col2_dashes = "─".repeat(col2_display);
    println!("┌{}┬{}┐", col1_dashes, col2_dashes);

    // Print rows
    for (key, value) in rows {
        let key_chars_count = key.chars().count();
        let key_padding = col1_inner - 2 - key_chars_count; // padding on right
        let key_str = format!(" {}{} ", key, " ".repeat(key_padding));

        let val_chars: Vec<char> = value.chars().collect();
        let val_str = if val_chars.len() > col2_content_max {
            // Truncate with +
            let truncated: String = val_chars[..col2_content_max - 1].iter().collect();
            format!("{}+", truncated)
        } else {
            value.clone()
        };

        let val_chars_count = val_str.chars().count();
        let val_padding = col2_inner - 2 - val_chars_count;
        let actual_col2_content_width = col2_display - 2;

        // Re-pad properly
        let val_display = if val_chars.len() > col2_content_max {
            // Truncated
            format!(" {} ", val_str)
        } else {
            let padding = actual_col2_content_width - val_chars_count;
            format!(" {}{} ", val_str, " ".repeat(padding))
        };

        println!("│{}│{}│", key_str, val_display);
    }

    // Print bottom border
    println!("└{}┴{}┘", col1_dashes, col2_dashes);
}

