new_render = '''fn render_table(rows: &[(String, String)]) {
    if rows.is_empty() {
        println!("┌──┐");
        println!("│  │");
        println!("└──┘");
        return;
    }

    let max_col1 = rows.iter().map(|(k, _)| k.chars().count()).max().unwrap_or(0);
    let max_col2 = rows.iter().map(|(_, v)| v.chars().count()).max().unwrap_or(0);

    let col1_inner = max_col1 + 2; // content + 2 spaces padding
    let col2_inner = max_col2 + 2; // content + 2 spaces padding

    // Total = 1 (│) + col1_inner + 1 (│) + col2_inner + 1 (│)
    let total_width = 1 + col1_inner + 1 + col2_inner + 1;

    // When total > 80, truncate the LARGER column (keep the smaller column natural)
    let (col1_display, col2_display) = if total_width <= 80 {
        (col1_inner, col2_inner)
    } else if col1_inner >= col2_inner {
        // col1 is larger: truncate col1, keep col2 natural
        let col1 = 80 - 1 - col2_inner - 1 - 1;
        (col1, col2_inner)
    } else {
        // col2 is larger: truncate col2, keep col1 natural
        let col2 = 80 - 1 - col1_inner - 1 - 1;
        (col1_inner, col2)
    };

    let col1_content_max = col1_display - 2; // content width for col1
    let col2_content_max = col2_display - 2; // content width for col2

    // Print top border
    let col1_dashes = "─".repeat(col1_display);
    let col2_dashes = "─".repeat(col2_display);
    println!("┌{}┬{}┐", col1_dashes, col2_dashes);

    // Print rows
    for (key, value) in rows {
        // Handle col1 (key) - may need truncation
        let key_chars: Vec<char> = key.chars().collect();
        let key_str = if key_chars.len() > col1_content_max {
            let truncated: String = key_chars[..col1_content_max - 1].iter().collect();
            format!("{}+", truncated)
        } else {
            key.clone()
        };
        let key_display_len = key_str.chars().count();
        let key_right_pad = col1_content_max - key_display_len;
        let key_padded = format!(" {}{} ", key_str, " ".repeat(key_right_pad));

        // Handle col2 (value) - may need truncation
        let val_chars: Vec<char> = value.chars().collect();
        let val_str = if val_chars.len() > col2_content_max {
            let truncated: String = val_chars[..col2_content_max - 1].iter().collect();
            format!("{}+", truncated)
        } else {
            value.clone()
        };
        let val_display_len = val_str.chars().count();
        let val_right_pad = col2_content_max - val_display_len;
        let val_padded = format!(" {}{} ", val_str, " ".repeat(val_right_pad));

        println!("│{}│{}│", key_padded, val_padded);
    }

    // Print bottom border
    println!("└{}┴{}┘", col1_dashes, col2_dashes);
}'''

